int Next(int x) { return ++x; }
void Main() {
    var i = 1;
    Print(i++ + ++i); Print(i);
    Print(--i + i--); Print(i);
    Print(-i++); Print(i);
    Print(Next(i)); Print(i);
    var max = 2147483647;
    Print(max++); Print(max); Print(--max);
    var wide = 9223372036854775807L;
    Print(++wide); Print(wide--); Print(wide);
}
